import re
P=open('explorations/coordinator/POSITIONS.md',encoding='utf-8').read().split('\n')
F=open('explorations/coordinator/FACTS.md',encoding='utf-8').read().split('\n')
def title(l):
    m=re.match(r'- \*\*(.+?)\*\*',l); return m.group(1) if m else l[2:]
pe={i:l for i,l in enumerate(P,1) if l.startswith('- ')}
fe={i:l for i,l in enumerate(F,1) if l.startswith('- ')}
def norm(s): return re.sub(r'[^a-z0-9]','',s.lower().replace('...','').replace('…',''))
def find(cites, ents):
    out=set()
    for c in cites:
        c=norm(c.rstrip('. '))[:40]
        if len(c)<8: continue
        for j,l in ents.items():
            if norm(title(l)).startswith(c) or norm(l[2:300]).startswith(c): out.add(j)
    return out
edges=set()
for i,l in pe.items():
    groups=re.findall(r'\(FACTS,? ((?:"[^"]+"(?:, | and |; )?)+)',l)
    cs=[]
    for g in groups: cs+=re.findall(r'"([^"]+)"',g)
    for j in find(cs,fe): edges.add((i,j,'P->F'))
for j,l in fe.items():
    cs=re.findall(r'POSITIONS,? "([^"]+)"',l)
    for i in find(cs,pe): edges.add((i,j,'F->P'))
pairs={}
for i,j,d in edges: pairs.setdefault((i,j),set()).add(d)
both=[k for k,v in pairs.items() if len(v)==2]
print('distinct P-F pairs linked',len(pairs),'linked both ways',len(both))
print('P entries in a pair',len({i for i,j in pairs}),'F entries in a pair',len({j for i,j in pairs}))
pb=sum(len(pe[i].encode()) for i in {i for i,j in pairs}); fb=sum(len(fe[j].encode()) for j in {j for i,j in pairs})
print('bytes: P',pb,'F',fb)
for (i,j) in sorted(both): print('  both:',i,title(pe[i])[:60],'<->',j,title(fe[j])[:60])
# Built clause bytes in POSITIONS
bb=0;n=0
for i,l in pe.items():
    for m in re.finditer(r'(Built[^.]*?(?:\([^)]*\))?[^.]*\.)',l):
        bb+=len(m.group(1).encode()); n+=1
print('Built sentences',n,'bytes',bb)
EOF

